  const rt::KvKey stale{prefix,"expired-owner",0};AWAIT(written,h::kvStub->set(stale,rt::KvValue("late stale owner body"),rt::KvSetOptions{.expireIn=h::EMBEDDINGS_IDEMPOTENCY_RESPONSE_TTL_MS}));(void)written;EXPECT_EQ(*h::kvExpirations.get(h::keyToString(stale)),h::EMBEDDINGS_IDEMPOTENCY_RESPONSE_TTL_MS);
  AWAIT(replay,h::handleUosEmbeddings(h::uosIdempotentRequest("key","input"),&context));EXPECT_EQ(replay.status(),200);EXPECT_EQ(replay.headers().get("x-uos-idempotency-replayed"),"true");AWAIT(replayed,replay.text());EXPECT_EQ(replayed,text);EXPECT_EQ(calls,1);
